"""Save a reviewable adaptation of the official train function; retain optimizer/scheduler/loss."""
from pathlib import Path
import ast
ROOT=Path(__file__).resolve().parents[2]
src=(ROOT/'policy/ViTAL/diffusion/train_policy.py').read_text()
node=next(n for n in ast.parse(src).body if isinstance(n,ast.FunctionDef) and n.name=='train')
s='\n'.join(src.splitlines()[node.lineno-1:node.end_lineno])+'\n'
s=s.replace("    debug.print=True", "    debug.print=False").replace("    debug.plot=True", "    debug.plot=False")
s=s.replace('        for epoch_idx in tglobal:\n','        for epoch_idx in tglobal:\n            nets.train()\n            epoch_loss = []\n')
# All selected views (including tactile RGB) are named in camera_names and independently encoded.
s=s.replace("                    if ABLATE_GEL: \n                        del nbatch['gelsight']", "                    if False: \n                        pass")
# Old visualization assumes 4-DoF real robot and a single depth/strain tactile image.
a=s.index('                            #save plot of first batch');b=s.index('            val_losses.append',a)
s=s[:a]+s[b:]
s=s.replace('            val_losses.append(np.mean(val_loss))','''            val_losses.append(np.mean(val_loss))
            record_epoch(epoch_idx, float(np.mean(epoch_loss)), float(np.mean(val_loss)), nets, epoch_idx % 10 == 0)
            if not np.isfinite(np.mean(epoch_loss)):
                raise RuntimeError('Nonfinite DP training loss')''')
(Path(__file__).parent/'dp_train_loop.py').write_text('''# Adapted from policy/ViTAL/diffusion/train_policy.py; generated by build_dp_loop.py.
import os
import numpy as np
import torch
import torch.nn as nn
from diffusers.optimization import get_scheduler
from tqdm.auto import tqdm
from datetime import datetime
from types import SimpleNamespace
DEVICE_STR='cuda:0'
ABLATE_GEL=True  # tactile RGB uses the generic per-view encoding path, NOT disabled in camera_names
START_TIME=datetime.now()
debug=SimpleNamespace()
'''+s)
